mapper.sql:
WHERE a.status = 1

    AND a.category_id = #{categoryId}


    AND a.author_id = #{authorId}


    AND (a.title LIKE CONCAT('%', #{keyword}, '%')
    OR c.name LIKE CONCAT('%', #{keyword}, '%'))

mapper.select:
SELECT a.*, c.name as category_name, c.category_alias, u.username as author_name FROM article a LEFT JOIN category c ON a.category_id = c.id LEFT JOIN user u ON a.author_id = u.id
ORDER BY a.create_time DESC
LIMIT #{start}, #{limit}
